        private static string CreateItemFilter(string asName, int aiItemCategoryId)
        {
            if (aiItemCategoryId == Constants.I_ZERO)
                return String.Format(" AND  (ItemCode LIKE N'%{0}%' OR ItemName LIKE N'%{0}%')", StringUtility.ReplaceSingleQuoteInString(asName, true));
            else
                return String.Format(" AND  (ItemCode LIKE N'%{0}%' OR ItemName LIKE N'%{0}%') AND (ItemCategoryId = {1})", StringUtility.ReplaceSingleQuoteInString(asName, true), StringUtility.ReplaceSingleQuoteInString(aiItemCategoryId.ToString(), true));
        }

